CREATE TABLE IF NOT EXISTS locations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, region VARCHAR(80) NOT NULL, latitude DECIMAL(9,6), longitude DECIMAL(9,6), seo_title VARCHAR(180), seo_description VARCHAR(255), active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS streams (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, location_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, stream_type ENUM('hls','iframe','image','link') NOT NULL, stream_url TEXT NOT NULL, source_name VARCHAR(120), source_page TEXT, active TINYINT(1) NOT NULL DEFAULT 1, featured TINYINT(1) NOT NULL DEFAULT 0, health_status ENUM('unknown','online','reported','offline') NOT NULL DEFAULT 'unknown', sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(location_id));
CREATE TABLE IF NOT EXISTS stream_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, stream_id INT UNSIGNED NULL, channel_slug VARCHAR(80) NOT NULL, issue VARCHAR(80) NOT NULL, details VARCHAR(500), status ENUM('new','reviewed','resolved') NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(channel_slug),INDEX(created_at));
CREATE TABLE IF NOT EXISTS channel_views (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, location_id INT UNSIGNED NULL, channel_slug VARCHAR(80) NOT NULL, view_date DATE NOT NULL, views INT UNSIGNED NOT NULL DEFAULT 1, UNIQUE KEY daily_channel(channel_slug,view_date));
CREATE TABLE IF NOT EXISTS forecast_cache (location_id INT UNSIGNED PRIMARY KEY, payload MEDIUMTEXT NOT NULL, fetched_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS news_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(220) NOT NULL, url TEXT NOT NULL, source VARCHAR(100), published_at DATETIME NULL, summary VARCHAR(500), active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO locations(slug,name,region,latitude,longitude,seo_title,seo_description) VALUES ('kingscliff','Kingscliff / Cudgen','Tweed Coast',-28.257000,153.579000,'Kingscliff Live Surf Cam & Forecast | CostaCams','Watch Kingscliff and Cudgen live beach camera and surf forecast.'),('cabarita','Cabarita Beach','Tweed Coast',-28.332000,153.570000,'Cabarita Beach Live Surf Cam & Forecast | CostaCams','Watch Cabarita Beach live and check the surf forecast.'),('tweed-heads','Tweed Heads','Tweed Coast',-28.171000,153.557000,'Tweed Heads Live Beach Cam & Forecast | CostaCams','Watch Tweed Heads coastal cameras and check surf conditions.'),('burleigh','Burleigh Heads','Gold Coast',-28.090000,153.453000,'Burleigh Heads Live Surf Cam & Forecast | CostaCams','Watch Burleigh Heads live surf camera and forecast.');
INSERT INTO streams(location_id,name,stream_type,stream_url,source_name,source_page,featured) SELECT id,'Cudgen Bar','iframe','https://widget.coastalcoms.com/video/73a52fac-d291-42be-a1f1-dd859c5dd28f','Transport for NSW','https://www.nsw.gov.au/driving-boating-and-transport/using-waterways-boating-and-transport-information/conditions-weather-and-tides/webcams/cudgen',1 FROM locations WHERE slug='kingscliff' AND NOT EXISTS(SELECT 1 FROM streams WHERE name='Cudgen Bar');
INSERT INTO streams(location_id,name,stream_type,stream_url,source_name,source_page,featured) SELECT id,'Cabarita Beach','iframe','https://embed.cdn-surfline.com/cams/5d482f6d6fe8473cf7ae1ce8/85f8446ad566cdab93b699ef13a83238ee563ac8','Surfline / The Beach Cabarita','https://www.thebeachcabarita.com.au/beach-cam/',1 FROM locations WHERE slug='cabarita' AND NOT EXISTS(SELECT 1 FROM streams WHERE name='Cabarita Beach');
